CREATE TABLE schema_migrations (version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE workspaces (id text PRIMARY KEY, name text NOT NULL, mode text NOT NULL DEFAULT 'preview' CHECK(mode IN ('preview','crm','sandbox')), environment text NOT NULL CHECK(environment IN ('local','sandbox')));
CREATE TABLE studio_users (id text PRIMARY KEY, email text UNIQUE NOT NULL, password_hash text, name text NOT NULL);
CREATE TABLE memberships (workspace_id text REFERENCES workspaces(id), user_id text REFERENCES studio_users(id), role text NOT NULL CHECK(role IN ('admin','tester','reviewer','viewer')), PRIMARY KEY(workspace_id,user_id));
CREATE TABLE auth_sessions (token_hash text PRIMARY KEY,user_id text REFERENCES studio_users(id),workspace_id text REFERENCES workspaces(id),expires_at timestamptz NOT NULL);
CREATE TABLE virtual_clients (workspace_id text REFERENCES workspaces(id), id text NOT NULL, data jsonb NOT NULL, PRIMARY KEY(workspace_id,id));
CREATE TABLE virtual_identities (workspace_id text NOT NULL, id text NOT NULL, client_id text NOT NULL, external_user_id text UNIQUE NOT NULL, data jsonb NOT NULL, PRIMARY KEY(workspace_id,id), FOREIGN KEY(workspace_id,client_id) REFERENCES virtual_clients(workspace_id,id));
CREATE TABLE conversation_refs (workspace_id text NOT NULL,id text NOT NULL,client_id text NOT NULL,identity_id text NOT NULL,external_chat_id text UNIQUE NOT NULL,lease_until timestamptz, data jsonb NOT NULL,PRIMARY KEY(workspace_id,id),FOREIGN KEY(workspace_id,client_id) REFERENCES virtual_clients(workspace_id,id),FOREIGN KEY(workspace_id,identity_id) REFERENCES virtual_identities(workspace_id,id));
CREATE TABLE agent_configurations (workspace_id text REFERENCES workspaces(id),id text NOT NULL,data jsonb NOT NULL,PRIMARY KEY(workspace_id,id));
CREATE TABLE prompt_versions (workspace_id text NOT NULL,id text NOT NULL,agent_id text NOT NULL,data jsonb NOT NULL,PRIMARY KEY(workspace_id,id),FOREIGN KEY(workspace_id,agent_id) REFERENCES agent_configurations(workspace_id,id));
CREATE TABLE agent_runs (workspace_id text NOT NULL,id text NOT NULL,conversation_id text NOT NULL,data jsonb NOT NULL,PRIMARY KEY(workspace_id,id),FOREIGN KEY(workspace_id,conversation_id) REFERENCES conversation_refs(workspace_id,id));
CREATE TABLE message_attempts (workspace_id text NOT NULL,id text NOT NULL,conversation_id text NOT NULL,external_message_id text NOT NULL,sequence bigint GENERATED ALWAYS AS IDENTITY,status text NOT NULL DEFAULT 'queued',next_at timestamptz NOT NULL DEFAULT now(),data jsonb NOT NULL,PRIMARY KEY(workspace_id,id),UNIQUE(workspace_id,conversation_id,external_message_id),FOREIGN KEY(workspace_id,conversation_id) REFERENCES conversation_refs(workspace_id,id));
CREATE INDEX attempt_queue ON message_attempts(status,next_at,sequence);
CREATE TABLE preview_messages (workspace_id text NOT NULL,id text NOT NULL,conversation_id text NOT NULL,data jsonb NOT NULL,PRIMARY KEY(workspace_id,id),FOREIGN KEY(workspace_id,conversation_id) REFERENCES conversation_refs(workspace_id,id));
CREATE TABLE transcript_snapshots (workspace_id text NOT NULL,id text NOT NULL,conversation_id text NOT NULL,data jsonb NOT NULL,PRIMARY KEY(workspace_id,id),FOREIGN KEY(workspace_id,conversation_id) REFERENCES conversation_refs(workspace_id,id));
CREATE TABLE tester_annotations (workspace_id text NOT NULL,id text NOT NULL,conversation_id text NOT NULL,data jsonb NOT NULL,PRIMARY KEY(workspace_id,id),FOREIGN KEY(workspace_id,conversation_id) REFERENCES conversation_refs(workspace_id,id));
CREATE TABLE test_scenarios (workspace_id text REFERENCES workspaces(id),id text NOT NULL,data jsonb NOT NULL,PRIMARY KEY(workspace_id,id));
CREATE TABLE scenario_runs (workspace_id text NOT NULL,id text NOT NULL,conversation_id text NOT NULL,scenario_id text NOT NULL,data jsonb NOT NULL,PRIMARY KEY(workspace_id,id),FOREIGN KEY(workspace_id,conversation_id) REFERENCES conversation_refs(workspace_id,id),FOREIGN KEY(workspace_id,scenario_id) REFERENCES test_scenarios(workspace_id,id));
CREATE TABLE media_assets (workspace_id text REFERENCES workspaces(id),id text NOT NULL,storage_key text UNIQUE NOT NULL,data jsonb NOT NULL,PRIMARY KEY(workspace_id,id));
CREATE TABLE call_sessions (workspace_id text NOT NULL,id text NOT NULL,conversation_id text NOT NULL,data jsonb NOT NULL,PRIMARY KEY(workspace_id,id),FOREIGN KEY(workspace_id,conversation_id) REFERENCES conversation_refs(workspace_id,id));
CREATE TABLE integration_mappings (workspace_id text REFERENCES workspaces(id),id text NOT NULL,data jsonb NOT NULL,PRIMARY KEY(workspace_id,id));
CREATE TABLE integration_configuration (workspace_id text REFERENCES workspaces(id),id text NOT NULL,data jsonb NOT NULL,PRIMARY KEY(workspace_id,id));
CREATE TABLE audit_logs (workspace_id text REFERENCES workspaces(id),id text NOT NULL,data jsonb NOT NULL,PRIMARY KEY(workspace_id,id));
CREATE TABLE simulation_sessions (workspace_id text NOT NULL,id text NOT NULL,conversation_id text NOT NULL,data jsonb NOT NULL,PRIMARY KEY(workspace_id,id),FOREIGN KEY(workspace_id,conversation_id) REFERENCES conversation_refs(workspace_id,id));
